<script setup lang="ts">
import { ArrowRight, Document, Paperclip, Star, Wallet } from '@element-plus/icons-vue'
import { computed } from 'vue'
import type { Place } from '@/types/itinerary'
import type { TripFile } from '@/types/tripFile'
import PlaceThumbnail from './PlaceThumbnail.vue'
const props = defineProps<{ places: Place[]; files: TripFile[]; estimate: number | null; budget: number | null }>()
const emit = defineEmits<{ open: [section: 'places' | 'files' | 'budget'] }>()
const progress = computed(() => props.budget && props.estimate !== null ? Math.min(100, props.estimate / props.budget * 100) : 0)
</script>
<template><div class="trip-utility-bar"><button class="utility-section" @click="emit('open','places')"><span class="utility-label"><el-icon><Star /></el-icon>已收藏地点<small>{{ places.length }}</small><el-icon class="utility-arrow"><ArrowRight /></el-icon></span><span v-if="places.length" class="utility-places"><span v-for="place in places.slice(0,3)" :key="place.id"><PlaceThumbnail :src="place.image_url" :name="place.name" :type="place.type" />{{ place.name }}</span></span><span v-else class="utility-empty">收藏喜欢的地点，慢慢安排</span></button><button class="utility-section" @click="emit('open','files')"><span class="utility-label"><el-icon><Paperclip /></el-icon>上传资料<small>{{ files.length }}</small><el-icon class="utility-arrow"><ArrowRight /></el-icon></span><span v-if="files.length" class="utility-files"><span v-for="file in files.slice(0,2)" :key="file.id"><el-icon><Document /></el-icon>{{ file.original_filename }}</span></span><span v-else class="utility-empty">添加机票、酒店订单或攻略</span></button><button class="utility-section" @click="emit('open','budget')"><span class="utility-label"><el-icon><Wallet /></el-icon>预算概览<el-icon class="utility-arrow"><ArrowRight /></el-icon></span><span class="utility-budget"><span class="budget-track"><span :class="{ over: budget !== null && estimate !== null && estimate > budget }" :style="{ width: `${progress}%` }" /></span><span><strong>{{ estimate === null ? '待估算' : `¥${estimate.toLocaleString('zh-CN')}` }}</strong><small> / {{ budget === null ? '未设置' : `¥${budget.toLocaleString('zh-CN')}` }}</small></span></span></button></div></template>
<style scoped>.trip-utility-bar{display:grid;grid-template-columns:1.2fr 1fr 1fr;gap:12px;margin-top:16px}.utility-section{display:flex;flex-direction:column;gap:12px;min-width:0;padding:13px 15px;border:0;border-radius:12px;background:white;color:var(--text);text-align:left;cursor:pointer}.utility-section:hover{background:#fafdff}.utility-label{display:flex;gap:8px;align-items:center;font-size:13px;font-weight:600}.utility-label>.el-icon{font-size:16px}.utility-label small{font-size:10px;font-weight:400;background:#f2f4fa;border-radius:5px;padding:1px 5px;color:#67738b}.utility-arrow{margin-left:auto;font-size:12px!important;color:#73819d}.utility-places,.utility-files{display:flex;gap:10px;min-width:0;overflow:hidden;font-size:11px;color:#6c768b;height:26px}.utility-places>span{display:flex;align-items:center;gap:6px;white-space:nowrap;min-width:0;overflow:hidden;text-overflow:ellipsis}.utility-places .place-thumbnail{height:26px;width:32px;border-radius:5px}.utility-files>span{display:flex;gap:5px;align-items:center;border:1px solid #e6eaf2;border-radius:5px;padding:4px 6px;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.utility-files .el-icon{color:var(--primary);font-size:14px;flex-shrink:0}.utility-budget{display:flex;align-items:center;gap:10px;height:26px;font-size:12px;white-space:nowrap}.utility-budget small{color:#77839b;font-size:11px}.budget-track{height:8px;flex:1;background:#e7ebf3;border-radius:5px;overflow:hidden;min-width:20px}.budget-track>span{display:block;height:100%;background:var(--primary);border-radius:5px}.budget-track>span.over{background:var(--danger)}.utility-empty{height:26px;display:flex;align-items:center;font-size:11px;color:#748099}@media(max-width:1399px){.trip-utility-bar{gap:8px}.utility-section{padding:13px 11px}.utility-budget{gap:6px}.utility-budget small{font-size:10px}}@media(max-width:759px){.trip-utility-bar{grid-template-columns:1fr}.utility-section{padding:15px}.utility-budget{max-width:100%}}
</style>
